using System.Collections.Generic;
using Deadzone.Data;
using UnityEngine;

namespace Deadzone.UI
{
    /// <summary>
    /// Runtime lookup for the HUD icon set (Resources/Icons, generated by Tools > DEADZONE > Generate Premium HUD).
    /// Returns null for an unknown name, so a missing icon never breaks a screen.
    /// </summary>
    public static class UiIcons
    {
        public const string ResourceFolder = "Icons/";

        private static readonly Dictionary<string, Sprite> Cache = new Dictionary<string, Sprite>();
        private static Sprite white;

        public static Sprite Get(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            if (Cache.TryGetValue(name, out Sprite cached) && cached != null) return cached;

            Sprite sprite = Resources.Load<Sprite>(ResourceFolder + name);
            Cache[name] = sprite;
            return sprite;
        }

        /// <summary>1x1 world unit white sprite (pivot left-centre) for bars drawn in world space.</summary>
        public static Sprite WhiteBar
        {
            get
            {
                if (white == null)
                {
                    white = Sprite.Create(Texture2D.whiteTexture, new Rect(0f, 0f, 4f, 4f), new Vector2(0f, 0.5f), 4f);
                    white.name = "WhiteBar";
                }
                return white;
            }
        }

        public static string ForResource(ResourceType type)
        {
            switch (type)
            {
                case ResourceType.Food: return "res_food";
                case ResourceType.Wood: return "res_wood";
                case ResourceType.Steel: return "res_steel";
                case ResourceType.Fuel: return "res_fuel";
                case ResourceType.Gold: return "res_gold";
                case ResourceType.Diamonds: return "res_diamond";
                default: return null;
            }
        }

        public static string ForFeature(HudFeature feature)
        {
            switch (feature)
            {
                case HudFeature.Base: return "nav_base";
                case HudFeature.Heroes: return "nav_heroes";
                case HudFeature.Troops: return "nav_troops";
                case HudFeature.TroopTraining: return "nav_troops";
                case HudFeature.Inventory: return "nav_inventory";
                case HudFeature.World: return "nav_world";
                case HudFeature.Alliance: return "nav_alliance";
                case HudFeature.Shop: return "nav_shop";
                case HudFeature.ConstructionQueue: return "side_construction";
                case HudFeature.ResearchQueue: return "side_research";
                case HudFeature.Missions: return "side_missions";
                case HudFeature.Vip: return "hud_vip";
                case HudFeature.Events: return "side_events";
                case HudFeature.EventCalendar: return "side_calendar";
                case HudFeature.DailyRewards: return "side_daily";
                case HudFeature.BattlePass: return "side_battlepass";
                case HudFeature.SpecialOffers: return "side_offers";
                default: return null;
            }
        }
    }
}
